import { useEffect, useMemo, useState } from 'react';
import { Link, Route, Routes, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { AnimatePresence, motion } from 'motion/react';
import { Activity, ArrowDownRight, ArrowRight, BadgeCheck, BusFront, CalendarDays, Check, ChevronDown, CircleHelp, GraduationCap, HeartHandshake, Library, LockKeyhole, MapPin, Menu, MessageCircle, School, Search, Shield, Sparkles, Star, Users, Wallet, X } from 'lucide-react';
import { Area, AreaChart, CartesianGrid, Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
