import { usePreferences, PreferenceProvider } from './preferences';
import { ForgotPassword, ResetPassword, VerifyEmail } from './pages/AccountRecovery';
import Billing from './pages/Billing';
import Insights from './pages/Insights';
import VerifyBanner from './components/VerifyBanner';
import SettingsPremium from './pages/SettingsPremium';
import Workspace from './pages/Workspace';
import PlatformAdmin from './pages/PlatformAdmin';
import { Toaster } from 'sonner';
const plans = [{ key: 'free', name: 'Free', description: 'A beautiful public introduction to your school.', bullets: ['Public school page', 'Admission inquiries', 'Up to 5 photos'] }, { key: 'basic', name: 'Basic', description: 'Everything your school needs for the everyday.', bullets: ['Students, families & classes', 'Attendance, homework & exams', 'Admission management', '30 photos'] }, { key: 'standard', name: 'Standard', description: 'Less admin for a more connected school.', bullets: ['Everything in Basic', 'Fees & online payments', 'Accountant & approved payroll', 'Library', '100 photos'] }, { key: 'premium', name: 'Premium', description: 'The full picture, from class to commute.', bullets: ['Everything in Standard', 'Bus management & live GPS', 'Featured school listing', 'Unlimited photos'] }];
const wrap = (fn) => (e) => { e.preventDefault(); fn(e); };
function Brand() { return <Link to="/" className="brand"><img className="brand-lockup" src="/shikshly-logo.svg" alt="Shikshly"/></Link>; }
function Nav() { const [open, setOpen] = useState(false); const { t } = usePreferences(); return <header className="site-nav"><div className="nav-inner"><Brand /><nav className={open ? 'nav-links nav-open' : 'nav-links'} aria-label="Main navigation"><a href="/#features">Platform</a><a href="/#plans">Plans</a><a href="/#schools">{t.findSchool}</a><Link to="/support">{t.support}</Link>{token() ? <><Link to="/workspace">Workspace</Link><Link to="/settings">{t.settings}</Link></> : <Link to="/privacy">Privacy</Link>}<Link to={token() ? '/dashboard' : '/login'} className="nav-login">{token() ? 'Dashboard' : 'Sign in'} <ArrowRight size={15}/></Link></nav><button className="icon-button mobile-menu" aria-label="Toggle menu" onClick={() => setOpen(!open)}>{open ? <X size={20}/> : <Menu size={20}/>}</button></div></header>; }
function Footer() { return <footer className="footer"><div className="footer-main"><Brand /><p>More time for the moments that matter.</p><div className="footer-links"><Link to="/privacy">Privacy</Link><Link to="/terms">Terms</Link><Link to="/cookies">Cookies</Link><a href="mailto:support@example.com">Contact</a></div></div><div className="footer-bottom"><span>© {new Date().getFullYear()} Shikshly</span><span>Made for the whole school community</span></div></footer>; }
function SectionLabel({ children }) { return <div className="section-label"><span></span>{children}</div>; }
function Home() {
    const [query, setQuery] = useState({ name: '', area: '', city: '' });
    const [schools, setSchools] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [plansData, setPlansData] = useState([]);
    const [location, setLocation] = useState(null);
    const [radiusKm, setRadiusKm] = useState('25');
    const navigate = useNavigate();
    useEffect(() => { request('/public/plans').then(setPlansData).catch(() => { }); }, []);
    const byKey = useMemo(() => new Map(plansData.map(p => [p.key, p])), [plansData]);
    const searchSchools = async (coords = location) => { setLoading(true); setError(''); try {
        const params = new URLSearchParams(Object.fromEntries(Object.entries(query).filter(([, v]) => v.trim())));
        if (coords) {
            params.set('lat', String(coords.lat));
            params.set('lon', String(coords.lon));
            params.set('radiusKm', radiusKm);
        }
        const result = await request(`/public/schools?${params}`);
        setSchools(result.items);
    }
    catch (err) {
        setError(err.message);
    }
    finally {
        setLoading(false);
    } };
    const find = (e) => { e.preventDefault(); void searchSchools(); };
    const findNearby = () => { setError(''); if (!navigator.geolocation) {
        setError('Location search is not available in this browser.');
        return;
    } navigator.geolocation.getCurrentPosition(position => { const coords = { lat: position.coords.latitude, lon: position.coords.longitude }; setLocation(coords); void searchSchools(coords); }, () => setError('We could not access your location. You can still search by school name, area, or city.'), { enableHighAccuracy: false, timeout: 10000, maximumAge: 300000 }); };
    return <><Nav /><main>
    <section className="hero"><div className="hero-copy"><SectionLabel>School management, with care</SectionLabel><h1>Make room for<br /><em>what matters.</em></h1><p className="hero-lede">The school day is full enough. Bring people, learning, and the little details into one calmer place.</p><div className="hero-actions"><Link className="button button-dark" to="/register">Register your school <ArrowRight size={17}/></Link><a className="text-link" href="#schools">Find a school <ArrowDownRight size={17}/></a></div><div className="proof-row"><div className="avatar-stack"><span>R</span><span>A</span><span>M</span><span>+</span></div><span>For the people who make a school</span><span className="proof-stars"><Star size={14} fill="currentColor"/> Thoughtful by design</span></div></div>
      <div className="hero-art"><div className="art-orbit orbit-one"></div><div className="art-orbit orbit-two"></div><div className="hero-sun"></div><div className="school-illustration"><div className="building-roof"></div><div className="building"><div className="building-sign"><span className="tiny-emblem"><GraduationCap size={19}/></span><span>OPEN<br />MINDS</span></div><div className="windows"><i /><i /><i /><i /><i /><i /></div><div className="door"></div></div><div className="building-base"></div></div><div className="floating-card attendance-float"><span className="float-icon green"><Activity size={17}/></span><span><b>Today's attendance</b><small>All classes are up to date</small></span><span className="float-check"><Check size={15}/></span></div><div className="floating-card family-float"><span className="float-icon peach"><HeartHandshake size={17}/></span><span><b>A closer school community</b><small>Messages, homework, and more</small></span></div><div className="leaf leaf-left">✳</div><div className="leaf leaf-right">✳</div></div>
    </section>
    <section className="trust-strip"><span>One steady place for</span><b><Users size={16}/> Families</b><b><GraduationCap size={16}/> Teachers</b><b><School size={16}/> School teams</b><b><BusFront size={16}/> School journeys</b></section>
    <section id="schools" className="discover section-shell"><div className="section-heading"><div><SectionLabel>Start with a school</SectionLabel><h2>Find the right <em>fit.</em></h2><p>Explore school profiles, get a feel for the community, and start an admission conversation.</p></div><div className="discover-note"><MapPin size={17}/><span>Search by name or area, or allow location access to sort nearby schools by distance.</span></div></div>
      <form className="school-search" onSubmit={find}><label><span>School name</span><div className="input-icon"><Search size={17}/><input value={query.name} onChange={e => setQuery({ ...query, name: e.target.value })} placeholder="Try a school name"/></div></label><label><span>Area or neighbourhood</span><div className="input-icon"><MapPin size={17}/><input value={query.area} onChange={e => setQuery({ ...query, area: e.target.value })} placeholder="e.g. Indiranagar"/></div></label><label><span>City</span><div className="input-icon"><MapPin size={17}/><input value={query.city} onChange={e => setQuery({ ...query, city: e.target.value })} placeholder="e.g. Bengaluru"/></div></label><label><span>Within</span><select value={radiusKm} onChange={e => setRadiusKm(e.target.value)}><option value="5">5 km</option><option value="10">10 km</option><option value="25">25 km</option><option value="50">50 km</option><option value="100">100 km</option></select></label><button className="button button-dark" disabled={loading}>{loading ? 'Searching…' : 'Explore schools'} <ArrowRight size={16}/></button><button type="button" className="button button-outline nearby-button" onClick={findNearby} disabled={loading}><MapPin size={16}/> Use my location</button></form>
      {error && <p role="alert" className="error-line">{error}</p>}{schools.length > 0 && <div className="school-grid">{schools.map((school, i) => <SchoolCard key={school.schoolId} school={school} index={i} onClick={() => navigate(`/schools/${school.slug}`)}/>)}</div>}{schools.length === 0 && <div className="search-hint"><span className="hint-mark"><Sparkles size={18}/></span><span><b>Looking for a school?</b><small>Your search results will appear here. A school can add its public profile after registering.</small></span><ArrowRight size={17}/></div>}
    </section>
    <section id="features" className="care-section"><div className="section-shell care-grid"><div className="care-copy"><SectionLabel>One school, many perspectives</SectionLabel><h2>Connected, without<br />the <em>noise.</em></h2><p>Give every person a clearer view of their day. Owners and principals see the whole school. Teachers stay close to their classes. Families see the things they need, when they need them.</p><Link to="/login" className="text-link">See your school space <ArrowRight size={16}/></Link></div><div className="feature-board"><div className="feature-main"><div className="board-top"><span className="board-logo"><School size={17}/></span><span>School overview</span><span className="board-period">This month <ChevronDown size={13}/></span></div><div className="board-title">A good month, together.</div><div className="board-stats"><div><small>Attendance</small><b>94.8%</b><span className="up">↑ 2.4%</span></div><div><small>Happy families</small><b>1,248</b><span>Across 18 classes</span></div><div><small>New inquiries</small><b>36</b><span>8 this week</span></div></div><div className="board-graph"><div className="graph-lines"><i /><i /><i /></div><svg viewBox="0 0 440 112" role="img" aria-label="Illustrative attendance trend rising over this month"><path d="M0 91 C35 82 48 87 72 67 S112 78 142 53 S187 68 216 43 S261 59 292 39 S338 51 365 25 S415 43 440 13" fill="none" stroke="#719384" strokeWidth="3" strokeLinecap="round"/><path d="M0 91 C35 82 48 87 72 67 S112 78 142 53 S187 68 216 43 S261 59 292 39 S338 51 365 25 S415 43 440 13 L440 112 L0 112Z" fill="url(#softFill)"/><defs><linearGradient id="softFill" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#719384" stopOpacity=".2"/><stop offset="1" stopColor="#719384" stopOpacity="0"/></linearGradient></defs></svg><div className="graph-days"><span>Week 1</span><span>Week 2</span><span>Week 3</span><span>Week 4</span></div></div></div><div className="board-note note-one"><span className="note-icon"><CalendarDays size={16}/></span><span><b>Every day in view</b><small>Attendance, without the scramble</small></span></div><div className="board-note note-two"><span className="note-icon"><MessageCircle size={16}/></span><span><b>Families feel in the loop</b><small>One connected conversation</small></span></div><div className="board-decoration"></div></div></div></section>
    <section className="section-shell plans-section" id="plans"><div className="plans-heading"><SectionLabel>Choose your pace</SectionLabel><h2>Start small. Grow <em>together.</em></h2><p>Pick the tools that suit your school today. Your plans are managed by the school owner.</p></div><div className="plan-grid">{plans.map((plan, i) => { const detail = byKey.get(plan.key); return <motion.article key={plan.key} className={`plan-card ${i === 2 ? 'plan-featured' : ''}`} whileHover={{ y: -5 }} transition={{ type: 'spring', stiffness: 280, damping: 22 }}>{i === 2 && <div className="plan-ribbon">MOST CHOSEN</div>}<div className="plan-kicker">{plan.name}</div><h3>{detail?.monthlyPaise ? `₹${(detail.monthlyPaise / 100).toLocaleString('en-IN')}` : 'Set your price later'}<small>{detail?.monthlyPaise ? '/ month' : '/ pricing set by you'}</small></h3><p>{plan.description}</p><Link to="/register" className={i === 2 ? 'button button-dark button-full' : 'button button-outline button-full'}>{plan.key === 'free' ? 'Create your school' : 'Get started'} <ArrowRight size={15}/></Link><ul>{plan.bullets.map(b => <li key={b}><Check size={14}/>{b}</li>)}</ul>{plan.key === 'basic' && <small className="plan-footnote">SMS packs are billed separately.</small>}</motion.article>; })}</div><p className="plan-disclaimer">Plan prices and SMS bundle quantities are configured by the platform owner. Prices shown above are intentionally unset.</p></section>
    <section className="privacy-banner section-shell"><div className="privacy-icon"><Shield size={22}/></div><div><b>Children's information deserves care.</b><p>Access is scoped to each school and the role a person has there. Privacy and consent settings should be reviewed before launch.</p></div><Link to="/privacy">Read about privacy <ArrowRight size={15}/></Link></section>
  </main><Footer /></>;
}
function SchoolCard({ school, index, onClick }) { return <motion.button onClick={onClick} className="school-card" initial={{ opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: index * .04 }}><div className="school-cover" style={school.photos?.[0] ? { backgroundImage: `linear-gradient(180deg,transparent,#172825aa),url(${school.photos[0]})` } : {}}><span className="school-symbol"><School size={21}/></span>{school.distanceKm !== undefined && <span className="distance-pill">{school.distanceKm} km away</span>}<span className="school-cover-label">{school.city || school.area || 'School community'}</span></div><div className="school-card-body"><div><h3>{school.name}</h3><p><MapPin size={14}/>{[school.area, school.city, school.state].filter(Boolean).join(', ') || 'Location not added yet'}</p></div><div className="school-rating"><Star size={14} fill="currentColor"/>{school.rating?.toFixed(1) || 'New'} <small>({school.reviewCount || 0})</small></div><span className="school-card-link">View profile <ArrowRight size={14}/></span></div></motion.button>; }
function SchoolDetail() {
    const { slug = '' } = useParams();
    const [school, setSchool] = useState(null);
    const [busy, setBusy] = useState(false);
    const [query, setQuery] = useState({ name: '', email: '', password: '', phone: '', message: '' });
    const [app, setApp] = useState({ studentName: '', dateOfBirth: '', requestedGrade: '' });
    const [msg, setMsg] = useState('');
    const [applicant, setApplicant] = useState(false);
    useEffect(() => { request(`/public/schools/${slug}`).then(setSchool).catch(e => setMsg(e.message)); }, [slug]);
    async function sendInquiry(e) { e.preventDefault(); setBusy(true); setMsg(''); try {
        const result = await request(`/public/schools/${slug}/inquiries`, { method: 'POST', body: JSON.stringify(query) });
        setToken(result.token);
        localStorage.setItem('school_token_type', 'applicant');
        setApplicant(true);
        setMsg('Your message is on its way. You can now continue your admission application.');
    }
    catch (e) {
        setMsg(e.message);
    }
    finally {
        setBusy(false);
    } }
    async function apply(e) { e.preventDefault(); setBusy(true); try {
        await request(`/applicant/schools/${slug}/applications`, { method: 'POST', body: JSON.stringify({ ...app, inquiryId: undefined }) });
        setMsg('Application sent. The school team can now review it.');
    }
    catch (e) {
        setMsg(e.message);
    }
    finally {
        setBusy(false);
    } }
    if (!school)
        return <><Nav /><main className="loading-panel">{msg || 'Loading school profile…'}</main><Footer /></>;
    return <><Nav /><main className="detail-shell"><Link to="/" className="back-link">← Back to schools</Link><div className="school-detail-hero"><div className="detail-photo" style={school.photos?.[0] ? { backgroundImage: `linear-gradient(0deg,#17282588,transparent),url(${school.photos[0]})` } : {}}><div className="photo-count"><span>{school.photos?.length || 0} photos</span><span>School profile</span></div></div><div className="detail-copy"><span className="detail-kicker"><BadgeCheck size={15}/> School profile</span><h1>{school.name}</h1><p className="detail-location"><MapPin size={16}/>{[school.area, school.city, school.state, school.country].filter(Boolean).join(', ') || 'Location coming soon'}</p><div className="detail-rating"><Star size={17} fill="currentColor"/> {school.rating?.toFixed(1) || 'New school'} <span>· {school.reviewCount || 0} reviews</span></div><p className="detail-description">{school.description || 'The school has not added an introduction yet. Send an inquiry to ask the school team about classes, facilities, and admissions.'}</p><div className="facility-list">{(school.facilities || []).map(f => <span key={f}>{f}</span>)}</div></div></div><div className="detail-columns"><section className="profile-gallery"><SectionLabel>A look around</SectionLabel><h2>A school is more than its <em>classrooms.</em></h2><div className="gallery-grid">{(school.photos || []).slice(0, 6).map((url, i) => <div key={url} className={`gallery-photo gallery-${i}`} style={{ backgroundImage: `url(${url})` }} aria-label={`School photo ${i + 1}`}/>)}{!school.photos?.length && <div className="gallery-placeholder"><School size={40}/><p>Photos will appear here when the school adds them.</p></div>}</div></section><aside className="admission-card"><div className="admission-top"><span className="admission-icon"><HeartHandshake size={20}/></span><span>Start a conversation</span></div><h2>Curious about a place <em>here?</em></h2><p>Send the school a note. Their admissions team can reply directly to your applicant account.</p>{school.admissionInquiriesEnabled && !applicant ? <form className="stack-form" onSubmit={sendInquiry}><label>Your name<input required minLength={2} value={query.name} onChange={e => setQuery({ ...query, name: e.target.value })}/></label><label>Email address<input required type="email" value={query.email} onChange={e => setQuery({ ...query, email: e.target.value })}/></label><label>Create a password<input required type="password" minLength={10} value={query.password} onChange={e => setQuery({ ...query, password: e.target.value })} placeholder="At least 10 characters"/></label><label>Phone (optional)<input type="tel" value={query.phone} onChange={e => setQuery({ ...query, phone: e.target.value })}/></label><label>What would you like to ask?<textarea required minLength={10} rows={4} value={query.message} onChange={e => setQuery({ ...query, message: e.target.value })} placeholder="Tell the school what you'd like to know"/></label><button className="button button-dark button-full" disabled={busy}>{busy ? 'Sending…' : 'Send admission inquiry'} <ArrowRight size={16}/></button></form> : null}
      {applicant && school.admissionsEnabled && <form className="stack-form" onSubmit={apply}><label>Student's name<input required value={app.studentName} onChange={e => setApp({ ...app, studentName: e.target.value })}/></label><label>Date of birth<input type="date" value={app.dateOfBirth} onChange={e => setApp({ ...app, dateOfBirth: e.target.value })}/></label><label>Class seeking admission<input required value={app.requestedGrade} onChange={e => setApp({ ...app, requestedGrade: e.target.value })}/></label><button className="button button-dark button-full" disabled={busy}>Submit application <ArrowRight size={16}/></button></form>}
      {!school.admissionInquiriesEnabled && <div className="notice-box">This school isn't accepting inquiries right now. Check back soon.</div>}{msg && <p className="form-message" role="status">{msg}</p>}<small className="form-privacy"><LockKeyhole size={13}/> Your inquiry is shared with this school's admissions team.</small></aside></div></main><Footer /></>;
}
function Register() { const [form, setForm] = useState({ schoolName: '', name: '', email: '', password: '' }); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const navigate = useNavigate(); const submit = async (e) => { e.preventDefault(); setBusy(true); try {
    const result = await request('/auth/register-school', { method: 'POST', body: JSON.stringify(form) });
    setToken(result.token);
    localStorage.setItem('school_token_type', 'member');
    navigate('/dashboard');
}
catch (err) {
    setError(err.message);
}
finally {
    setBusy(false);
} }; return <AuthLayout eyebrow="A new chapter" title={<>Bring your school<br /><em>into one place.</em></>} subtitle="Create your school workspace. You can add a public profile, invite your people, and choose a plan when you're ready."><form className="stack-form" onSubmit={wrap(submit)}><label>School name<input required minLength={2} value={form.schoolName} onChange={e => setForm({ ...form, schoolName: e.target.value })}/></label><label>Your name<input required minLength={2} value={form.name} onChange={e => setForm({ ...form, name: e.target.value })}/></label><label>Work email<input required type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })}/></label><label>Password<input required type="password" minLength={10} value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} placeholder="At least 10 characters"/></label>{error && <p className="error-line" role="alert">{error}</p>}<button disabled={busy} className="button button-dark button-full">{busy ? 'Creating…' : 'Create school space'} <ArrowRight size={16}/></button><small className="form-privacy"><Shield size={13}/> Your school starts on the Free plan. Set pricing when you are ready.</small></form></AuthLayout>; }
function Login() { const [form, setForm] = useState({ email: '', password: '', schoolId: '', context: 'member' }); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const nav = useNavigate(); const submit = async (e) => { e.preventDefault(); setBusy(true); try {
    const result = await request('/auth/login', { method: 'POST', body: JSON.stringify({ ...form, schoolId: form.schoolId || undefined }) });
    setToken(result.token);
    localStorage.setItem('school_token_type', result.tokenType);
    nav('/dashboard');
}
catch (err) {
    setError(err.message);
}
finally {
    setBusy(false);
} }; return <AuthLayout eyebrow="Welcome back" title={<>A steadier start<br />to the <em>school day.</em></>} subtitle="Sign in to your school workspace or applicant account."><form className="stack-form" onSubmit={wrap(submit)}><label>I'm signing in as<select value={form.context} onChange={e => setForm({ ...form, context: e.target.value })}><option value="member">School team / family member</option><option value="applicant">Admission applicant</option><option value="platform_admin">Platform administrator</option></select></label><label>Email address<input required type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })}/></label><label>Password<input required type="password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })}/></label>{form.context === 'member' && <label>School ID <small>(only needed if your account belongs to more than one school)</small><input value={form.schoolId} onChange={e => setForm({ ...form, schoolId: e.target.value })}/></label>}{error && <p className="error-line" role="alert">{error}</p>}<button disabled={busy} className="button button-dark button-full">{busy ? 'Signing in…' : 'Sign in securely'} <ArrowRight size={16}/></button><p className="auth-switch"><Link to="/forgot-password">Forgot your password?</Link></p><p className="auth-switch">New school? <Link to="/register">Register here</Link></p></form></AuthLayout>; }
function AuthLayout({ eyebrow, title, subtitle, children }) { return <><Nav /><main className="auth-shell"><div className="auth-story"><SectionLabel>{eyebrow}</SectionLabel><h1>{title}</h1><p>{subtitle}</p><div className="auth-illustration"><div className="auth-circle"><GraduationCap size={46}/></div><div className="auth-star">✦</div><div className="auth-orbit"></div></div></div><div className="auth-card">{children}</div></main><Footer /></>; }
function Join() { const { code = '' } = useParams(); const [form, setForm] = useState({ name: '', email: '', password: '' }); const [error, setError] = useState(''); const nav = useNavigate(); const submit = async (e) => { e.preventDefault(); try {
    const result = await request('/auth/join', { method: 'POST', body: JSON.stringify({ ...form, code }) });
    setToken(result.token);
    localStorage.setItem('school_token_type', 'member');
    nav('/dashboard');
}
catch (err) {
    setError(err.message);
} }; return <AuthLayout eyebrow="Your invitation" title={<>You're part of<br />the <em>school story.</em></>} subtitle="Finish setting up your account to join your school. Keep the invite code private."><form className="stack-form" onSubmit={wrap(submit)}><div className="invite-code"><span>Invitation code</span><b>{code}</b></div><label>Your name<input required value={form.name} onChange={e => setForm({ ...form, name: e.target.value })}/></label><label>Email address<input required type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })}/></label><label>Choose a password<input required type="password" minLength={10} value={form.password} onChange={e => setForm({ ...form, password: e.target.value })}/></label>{error && <p role="alert" className="error-line">{error}</p>}<button className="button button-dark button-full">Join your school <ArrowRight size={16}/></button><Link className="download-link" to={`/download?invite=${encodeURIComponent(code)}`}>Need the app? See install options</Link></form></AuthLayout>; }
function Download() { const [params] = useSearchParams(); const code = params.get('invite') || ''; const android = import.meta.env.VITE_ANDROID_STORE_URL || ''; const ios = import.meta.env.VITE_IOS_STORE_URL || ''; return <><Nav /><main className="download-page"><div className="download-card"><span className="download-icon"><GraduationCap size={28}/></span><SectionLabel>Shikshly mobile</SectionLabel><h1>Your school,<br /><em>in your pocket.</em></h1><p>Teachers, parents, and students can use the mobile app to check attendance, homework, and school updates.</p>{code && <div className="invite-code"><span>Your school invite</span><b>{code}</b><Link to={`/join/${encodeURIComponent(code)}`}>Continue on the web <ArrowRight size={14}/></Link></div>}<div className="store-row">{android ? <a className="button button-dark" href={android}>Get it on Google Play <ArrowRight size={15}/></a> : <span className="store-pending">Google Play listing will be added before launch</span>}{ios ? <a className="button button-outline" href={ios}>Download on App Store</a> : <span className="store-pending">App Store listing will be added before launch</span>}</div><Link className="text-link" to={code ? `/join/${encodeURIComponent(code)}` : '/login'}>Continue in browser <ArrowRight size={15}/></Link></div></main><Footer /></>; }
function Dashboard() {
    const [profile, setProfile] = useState(null);
    const [overview, setOverview] = useState(null);
    const [children, setChildren] = useState([]);
    const [selected, setSelected] = useState('');
    const [attendance, setAttendance] = useState(null);
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(true);
    const nav = useNavigate();
    useEffect(() => { if (!token()) {
        nav('/login');
        return;
    } request('/auth/me').then(async (data) => { setProfile({ user: data.user, role: data.role, schoolId: data.schoolId, plan: data.plan }); if (['owner', 'principal'].includes(data.role))
        setOverview(await request('/school/dashboard/overview')); if (data.role === 'parent')
        setChildren(await request('/school/students')); }).catch(e => setError(e.message)).finally(() => setLoading(false)); }, []);
    useEffect(() => { if (profile?.role === 'parent' && selected)
        request(`/learning/me/children/${selected}/attendance/last-30-days`).then(setAttendance).catch(e => setError(e.message)); }, [profile, selected]);
    const logout = () => { clearToken(); localStorage.removeItem('school_token_type'); nav('/login'); };
    if (loading)
        return <><Nav /><main className="loading-panel">Preparing your school view…</main><Footer /></>;
    const role = profile?.role || 'member';
    return <><Nav /><main className="dashboard-shell"><div className="dashboard-head"><div><SectionLabel>Your school, in view</SectionLabel><h1>Good morning, {profile?.user?.name?.split(' ')[0] || 'there'}<span className="period">.</span></h1><p>A little more clarity for the day ahead.</p></div><div className="dashboard-actions"><span className="role-chip">{role.replace('_', ' ')} view</span><button className="button button-outline" onClick={logout}>Sign out <ArrowRight size={15}/></button></div></div>{error && <div className="notice-box" role="alert">{error} <Link to="/login">Sign in again</Link></div>}
    <VerifyBanner />{role === 'owner' && <p><Link className="button button-dark" to="/billing">Plan and billing</Link></p>}
    {['owner', 'principal'].includes(role) && overview && <OwnerDashboard data={overview}/>}
    {role === 'parent' && <section className="parent-attendance"><div className="chart-header"><div><SectionLabel>Your family's view</SectionLabel><h2>Thirty days, <em>at a glance.</em></h2><p>Attendance records for your child, school day by school day.</p></div><label className="select-label">Choose a child<select value={selected} onChange={e => setSelected(e.target.value)}><option value="">Select a child</option>{children.map(c => <option key={c._id} value={c._id}>{c.name} · {c.admissionNo || 'Student'}</option>)}</select></label></div>{attendance ? <AttendanceView data={attendance}/> : <div className="empty-chart">{children.length ? 'Choose a child to see their last 30 days.' : 'No linked students found for this account.'}</div>}</section>}
    {role === 'teacher' && <TeacherDashboard />}{role === 'student' && <StudentDashboard />}{!['owner', 'principal', 'parent', 'student'].includes(role) && <Insights />}
  </main><Footer /></>;
}
function Stat({ icon: Icon, label, value, detail, accent = 'green' }) { return <motion.article className="stat-card" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}><span className={`stat-icon ${accent}`}><Icon size={18}/></span><span className="stat-label">{label}</span><b>{value}</b><small>{detail}</small></motion.article>; }
function OwnerDashboard({ data }) { const [year, setYear] = useState(''); const [years, setYears] = useState([]); const [view, setView] = useState(data); useEffect(() => { request('/school/academic-years').then(setYears).catch(() => { }); }, []); useEffect(() => { if (year)
    request(`/school/dashboard/overview?academicYearId=${year}`).then(setView).catch(() => { });
else
    setView(data); }, [year, data]); const cards = view.cards; return <><div className="dashboard-context"><span><CalendarDays size={15}/>{view.academicYear?.name || 'Current academic year'}</span><label className="select-label"><span className="sr-only">Academic year filter</span><select value={year} onChange={e => setYear(e.target.value)}><option value="">Current year</option>{years.map(y => <option key={y._id} value={y._id}>{y.name}</option>)}</select></label></div><div className="stats-grid"><Stat icon={Users} label="Active students" value={cards.activeStudents} detail={`${cards.classes} classes in this view`}/><Stat icon={GraduationCap} label="Teaching team" value={cards.teachers} detail={`${cards.activeMembers} active school members`} accent="blue"/><Stat icon={HeartHandshake} label="Families" value={cards.parents} detail="Connected to the school" accent="peach"/><Stat icon={MessageCircle} label="Admission inquiries" value={cards.openAdmissionInquiries} detail={`${cards.pendingApplications} applications in review`} accent="purple"/><Stat icon={Wallet} label="Fees collected" value={money(cards.feesCollectedPaise)} detail={`${money(cards.feesOutstandingPaise)} still outstanding`} accent="gold"/><Stat icon={Library} label="Library" value={cards.libraryBooks} detail={`${cards.openLibraryLoans} books currently loaned`} accent="blue"/><Stat icon={MessageCircle} label="SMS used" value={cards.smsSentThisMonth} detail="Sent this month" accent="gold"/></div><div className="analytics-grid"><article className="analytics-card attendance-analytics"><div className="chart-header"><div><SectionLabel>School pulse</SectionLabel><h2>Attendance <em>over time.</em></h2></div><span className="chart-legend"><i></i>Attendance rate</span></div><div className="chart-wrap"><ResponsiveContainer width="100%" height={270}><AreaChart data={view.graphs.attendance30Days} accessibilityLayer margin={{ top: 10, right: 12, left: -20, bottom: 0 }}><defs><linearGradient id="attendanceFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#668a78" stopOpacity={.25}/><stop offset="100%" stopColor="#668a78" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#e8ece5" vertical={false}/><XAxis dataKey="date" tickFormatter={(v) => v.slice(5)} tickLine={false} axisLine={false} tick={{ fill: '#8a9590', fontSize: 11 }} interval={4}/><YAxis tickLine={false} axisLine={false} domain={[0, 100]} tickFormatter={(v) => `${v}%`} tick={{ fill: '#8a9590', fontSize: 11 }}/><Tooltip formatter={(v) => v === null ? 'No records' : `${v}%`} labelFormatter={(v) => `Date ${v}`}/><Area type="monotone" dataKey="attendanceRate" name="Attendance" stroke="#668a78" strokeWidth={3} fill="url(#attendanceFill)" connectNulls={false}/></AreaChart></ResponsiveContainer></div></article><article className="analytics-card admission-analytics"><div className="chart-header"><div><SectionLabel>Growing community</SectionLabel><h2>Admission <em>journey.</em></h2></div></div><div className="chart-wrap"><ResponsiveContainer width="100%" height={210}><PieChart accessibilityLayer><Pie data={view.graphs.admissionsByStatus} dataKey="count" nameKey="status" innerRadius={56} outerRadius={83} paddingAngle={4} stroke="none"><Cell fill="#668a78"/><Cell fill="#e9b76e"/><Cell fill="#9ba8c2"/><Cell fill="#d58b79"/><Cell fill="#c2cfc5"/></Pie><Tooltip /></PieChart></ResponsiveContainer></div><div className="stage-list">{view.graphs.admissionsByStatus.slice(0, 4).map((s, i) => <span key={s.status}><i className={`stage-dot stage-${i}`}/>{s.status.replace('_', ' ')} <b>{s.count}</b></span>)}</div></article><article className="analytics-card fee-analytics"><div className="chart-header"><div><SectionLabel>Keeping things steady</SectionLabel><h2>Fee <em>collections.</em></h2></div><span className="chart-legend"><i className="legend-gold"/>Collected</span></div><div className="chart-wrap"><ResponsiveContainer width="100%" height={235}><AreaChart data={view.graphs.feeCollections12Months} accessibilityLayer margin={{ top: 10, right: 12, left: 0, bottom: 0 }}><defs><linearGradient id="feeFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#eab96f" stopOpacity={.25}/><stop offset="100%" stopColor="#eab96f" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#e8ece5" vertical={false}/><XAxis dataKey="label" tickLine={false} axisLine={false} tick={{ fill: '#8a9590', fontSize: 11 }}/><YAxis tickLine={false} axisLine={false} tickFormatter={(v) => `₹${Math.round(v / 100000)}`} tick={{ fill: '#8a9590', fontSize: 11 }}/><Tooltip formatter={(v) => money(v)}/><Area type="monotone" dataKey="amountPaise" name="Fees" stroke="#d39d53" strokeWidth={3} fill="url(#feeFill)"/></AreaChart></ResponsiveContainer></div></article><article className="analytics-card activity-analytics"><div className="chart-header"><div><SectionLabel>What's happening</SectionLabel><h2>Recent <em>activity.</em></h2></div><Link className="mini-link" to="/dashboard">View all <ArrowRight size={14}/></Link></div><div className="activity-list">{view.recentActivity.length ? view.recentActivity.slice(0, 6).map((a) => <div className="activity-row" key={`${a.entityId}-${a.action}-${a.createdAt}`}><span className="activity-bullet"><Activity size={14}/></span><span><b>{a.action.replaceAll('_', ' ')}</b><small>{a.role || 'Team member'} · {new Date(a.createdAt).toLocaleString()}</small></span></div>) : <p className="muted">School activity will appear here as your team works.</p>}</div></article></div><p className="dashboard-footnote"><Shield size={14}/> Dashboard data is limited to your school. Attendance records marked “not recorded” are not counted as absences.</p></>; }
function money(paise) { return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format((paise || 0) / 100); }
function AttendanceView({ data }) { const formatted = data.days.map((d) => ({ ...d, label: new Date(`${d.date}T12:00:00`).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' }), value: d.status === 'present' ? 100 : d.status === 'late' ? 75 : d.status === 'absent' ? 0 : d.status === 'excused' ? 40 : null })); return <><div className="attendance-summary"><div><small>Attendance rate</small><b>{data.summary.attendanceRate === null ? '—' : `${data.summary.attendanceRate}%`}</b><span>Present or late on marked days</span></div><div><small>Present</small><b>{data.summary.present}</b><span>of {data.summary.markedDays} marked days</span></div><div><small>Absent</small><b>{data.summary.absent}</b><span>School records</span></div><div><small>Not recorded</small><b>{data.summary.notRecorded}</b><span>Not treated as absent</span></div></div><div className="chart-wrap parent-chart"><ResponsiveContainer width="100%" height={270}><LineChart data={formatted} accessibilityLayer margin={{ top: 14, right: 12, left: -20, bottom: 0 }}><CartesianGrid stroke="#e8ece5" vertical={false}/><XAxis dataKey="label" tickLine={false} axisLine={false} tick={{ fill: '#8a9590', fontSize: 10 }} interval={4}/><YAxis domain={[0, 100]} tickFormatter={(v) => `${v}%`} tickLine={false} axisLine={false} tick={{ fill: '#8a9590', fontSize: 11 }}/><Tooltip labelFormatter={(_, items) => items?.[0]?.payload?.date || ''} formatter={(_, name, props) => [props.payload.status.replace('_', ' '), name]}/><Line type="monotone" dataKey="value" name="School day" stroke="#668a78" strokeWidth={2.5} dot={{ r: 4, fill: '#668a78', stroke: '#fff', strokeWidth: 2 }} activeDot={{ r: 6 }} connectNulls={false}/></LineChart></ResponsiveContainer></div><div className="attendance-key"><span><i className="key-dot present"/>Present</span><span><i className="key-dot absent"/>Absent</span><span><i className="key-dot late"/>Late</span><span><i className="key-dot excused"/>Excused</span><span><i className="key-dot not-recorded"/>Not recorded</span></div><div className="day-strip">{formatted.map((d) => <div key={d.date} className={`day-cell ${d.status}`} title={`${d.date}: ${d.status}`}><small>{d.label.split(' ')[0]}</small><span>{d.status === 'present' ? 'P' : d.status === 'absent' ? 'A' : d.status === 'late' ? 'L' : d.status === 'excused' ? 'E' : '·'}</span></div>)}</div><p className="chart-caption">{data.student.name} · {data.from} to {data.to} · School timezone: {data.timezone}</p></>; }
function TeacherDashboard() { const [classes, setClasses] = useState([]); const [room, setRoom] = useState(''); const [date, setDate] = useState(new Date().toISOString().slice(0, 10)); const [roster, setRoster] = useState([]); const [msg, setMsg] = useState(''); useEffect(() => { request('/school/classes').then(rows => { setClasses(rows); if (rows[0])
    setRoom(rows[0]._id); }).catch(e => setMsg(e.message)); }, []); useEffect(() => { if (room)
    request(`/learning/attendance/classes/${room}/${date}`).then(setRoster).catch(e => setMsg(e.message)); }, [room, date]); return <section className="teacher-panel"><div className="chart-header"><div><SectionLabel>Your classroom</SectionLabel><h2>Keep your class <em>close.</em></h2><p>Only classes assigned to your teacher account appear here.</p></div></div><div className="teacher-controls"><label>Class<select value={room} onChange={e => setRoom(e.target.value)}>{classes.map(c => <option key={c._id} value={c._id}>{c.name} {c.section}</option>)}</select></label><label>School day<input type="date" value={date} onChange={e => setDate(e.target.value)}/></label></div>{msg && <p role="status" className="form-message">{msg}</p>}<div className="roster-list">{roster.map(s => <div className="roster-row" key={s._id}><span className="student-avatar">{s.name?.slice(0, 1)}</span><b>{s.name}</b><span className="roster-id">{s.admissionNo || 'Student'}</span><span className={`status-chip ${s.attendance?.status || 'not_recorded'}`}>{s.attendance?.status || 'Not recorded'}</span></div>)}{!roster.length && <p className="empty-chart">No roster for this class and day yet.</p>}</div></section>; }
function StudentDashboard() { return <div className="empty-chart"><GraduationCap size={22}/> Your school updates, attendance, and homework will show here.</div>; }
function SettingsPage() {
  const { prefs, update, t } = usePreferences();
  const [appRating, setAppRating] = useState(null); const [myRating, setMyRating] = useState(null); const [appFeedback, setAppFeedback] = useState(''); const [ratingMsg, setRatingMsg] = useState('');
  const [data, setData] = useState(null); const [form, setForm] = useState({}); const [msg, setMsg] = useState(''); const [error, setError] = useState('');
  useEffect(() => { if (!token()) return; request('/school/settings').then(r => { setData(r); setForm({ name: r.user?.name || '', phone: r.user?.phone || '', theme: r.preferences?.theme || prefs.theme, language: r.preferences?.language || prefs.language, emailNotifications: r.preferences?.emailNotifications ?? true, smsNotifications: r.preferences?.smsNotifications ?? true, productUpdates: r.preferences?.productUpdates ?? true }); }).catch(e => setError(e.message)); }, []);
  useEffect(() => { if (!token()) return; Promise.all([request('/school/app-rating/me'), request('/public/app-rating')]).then(([mine, summary]) => { setMyRating(mine?.rating || 0); setAppFeedback(mine?.feedback || ''); setAppRating(summary); }).catch(()=>{}); }, []);
  const saveAppRating = async () => { if (!myRating) return; try { await request('/school/app-rating/me', { method:'PUT', body: JSON.stringify({ rating: myRating, feedback: appFeedback, platform:'web', appVersion: '1.0.0' }) }); setRatingMsg('Thanks for rating Shikshly.'); const summary=await request('/public/app-rating'); setAppRating(summary); } catch(e){ setRatingMsg(e.message); } };
  const save = async (e) => { e.preventDefault(); setMsg(''); setError(''); try { const r = await request('/school/settings', { method: 'PATCH', body: JSON.stringify(form) }); setData(r); await update(form); setMsg(t.saved); } catch (e) { setError(e.message); } };
  if (!token()) return <><Nav/><main className="loading-panel"><h1>Sign in to manage settings.</h1><Link to="/login" className="button button-dark">Sign in <ArrowRight size={16}/></Link></main><Footer/></>;
  return <><Nav/><main className="settings-shell"><div className="settings-hero"><SectionLabel>{t.settings}</SectionLabel><h1>Make Shikshly <em>yours.</em></h1><p>Control your account, appearance, language and notifications. Preferences are saved to your account when you are signed in.</p></div><form className="settings-grid" onSubmit={save}><section className="settings-card"><div className="settings-card-head"><span className="float-icon green"><Users size={18}/></span><div><h2>{t.account}</h2><p>Your basic account information.</p></div></div><label>{t.name}<input value={form.name || ''} onChange={e=>setForm({...form,name:e.target.value})} minLength={2}/></label><label>{t.email}<input value={data?.user?.email || ''} disabled/></label><label>{t.phone}<input value={form.phone || ''} onChange={e=>setForm({...form,phone:e.target.value})}/></label></section><section className="settings-card"><div className="settings-card-head"><span className="float-icon peach"><Sparkles size={18}/></span><div><h2>{t.theme}</h2><p>Choose how Shikshly looks on this device.</p></div></div><div className="segmented"><button type="button" className={form.theme==='system'?'active':''} onClick={()=>setForm({...form,theme:'system'})}>{t.system}</button><button type="button" className={form.theme==='light'?'active':''} onClick={()=>setForm({...form,theme:'light'})}>{t.light}</button><button type="button" className={form.theme==='dark'?'active':''} onClick={()=>setForm({...form,theme:'dark'})}>{t.dark}</button></div><label>{t.language}<select value={form.language || 'en'} onChange={e=>setForm({...form,language:e.target.value})}><option value="en">English</option><option value="hi">हिन्दी</option></select></label></section><section className="settings-card"><div className="settings-card-head"><span className="float-icon purple"><MessageCircle size={18}/></span><div><h2>{t.notifications}</h2><p>Choose which service updates you want to receive.</p></div></div><label className="switch-row"><span>Email notifications</span><input type="checkbox" checked={form.emailNotifications ?? true} onChange={e=>setForm({...form,emailNotifications:e.target.checked})}/></label><label className="switch-row"><span>SMS notifications</span><input type="checkbox" checked={form.smsNotifications ?? true} onChange={e=>setForm({...form,smsNotifications:e.target.checked})}/></label><label className="switch-row"><span>Product updates</span><input type="checkbox" checked={form.productUpdates ?? true} onChange={e=>setForm({...form,productUpdates:e.target.checked})}/></label></section><section className="settings-card"><div className="settings-card-head"><span className="float-icon gold"><Star size={18}/></span><div><h2>Rate Shikshly</h2><p>This rating is for the app, not for your school.</p></div></div><div className="app-rating-stars">{[1,2,3,4,5].map(n=><button type="button" key={n} aria-label={`${n} stars`} onClick={()=>setMyRating(n)} className={n <= (myRating||0) ? 'active' : ''}><Star size={24} fill="currentColor"/></button>)}</div><textarea rows={3} value={appFeedback} onChange={e=>setAppFeedback(e.target.value)} placeholder="Tell us how we can improve Shikshly (optional)"/><div className="rating-footer"><span>{appRating ? `Shikshly ${appRating.average.toFixed(1)} / 5 · ${appRating.count} ratings` : 'Be the first to rate'}</span><button type="button" className="button button-outline" onClick={saveAppRating}>Submit rating</button></div>{ratingMsg&&<p className="form-message">{ratingMsg}</p>}</section>
<section className="settings-card settings-support-card"><div><SectionLabel>{t.help}</SectionLabel><h2>{t.contactSupport}</h2><p>Report billing, SMS, admission or technical issues and keep the whole conversation in one ticket.</p></div><Link to="/support" className="button button-outline">Open support <ArrowRight size={15}/></Link></section><div className="settings-save"><span>{error && <span className="error-line">{error}</span>}{msg && <span className="form-message">{msg}</span>}</span><button className="button button-dark" type="submit">{t.save} <ArrowRight size={15}/></button></div></form></main><Footer/></>;
}
function SupportPage() {
  const [tickets,setTickets]=useState([]); const [subject,setSubject]=useState(''); const [body,setBody]=useState(''); const [msg,setMsg]=useState(''); const [busy,setBusy]=useState(false); const [open,setOpen]=useState(null); const [messages,setMessages]=useState([]); const { t }=usePreferences();
  const load=()=>request('/operations/support').then(setTickets).catch(e=>setMsg(e.message)); useEffect(()=>{ if(token()) load(); },[]);
  const create=async e=>{e.preventDefault();setBusy(true);try{await request('/operations/support',{method:'POST',body:JSON.stringify({subject,body})});setSubject('');setBody('');setMsg('Ticket created. Our team can continue the conversation here.');load();}catch(e){setMsg(e.message)}finally{setBusy(false)}};
  const view=async id=>{setOpen(id);try{setMessages(await request(`/operations/support/${id}/messages`))}catch(e){setMsg(e.message)}};
  return <><Nav/><main className="support-shell"><div className="settings-hero"><SectionLabel>{t.support}</SectionLabel><h1>Help that stays <em>with you.</em></h1><p>Create a support ticket for SMS, billing, admissions, account or technical issues. Owners and principals can follow replies without leaving Shikshly.</p></div>{token()?<div className="support-layout"><form className="settings-card stack-form" onSubmit={create}><h2>Create a ticket</h2><label>Subject<input required minLength={3} value={subject} onChange={e=>setSubject(e.target.value)} placeholder="e.g. SMS delivery is failing"/></label><label>Message<textarea required minLength={10} rows={7} value={body} onChange={e=>setBody(e.target.value)} placeholder="Tell us what happened, what you expected, and any useful reference number."/></label>{msg&&<p className="form-message">{msg}</p>}<button className="button button-dark" disabled={busy}>{busy?'Creating…':'Create support ticket'} <ArrowRight size={15}/></button></form><section className="settings-card"><div className="settings-card-head"><span className="float-icon green"><CircleHelp size={18}/></span><div><h2>Your tickets</h2><p>Track status and replies.</p></div></div><div className="ticket-list">{tickets.map(t=><article key={t._id} className="ticket-row" onClick={()=>view(t._id)}><div><b>{t.subject}</b><small>{new Date(t.createdAt).toLocaleString('en-IN')}</small></div><span className={`status-chip ${t.status}`}>{t.status.replace('_',' ')}</span></article>)}{!tickets.length&&<div className="empty-chart">No tickets yet. If you need us, start a conversation.</div>}</div>{open&&<div className="ticket-thread"><h3>Conversation</h3>{messages.map(m=><div className="ticket-message" key={m._id}><b>{m.senderRole||'Support'}</b><p>{m.body}</p><small>{new Date(m.createdAt).toLocaleString('en-IN')}</small></div>)}{!messages.length&&<p className="muted">No replies yet.</p>}</div>}</section></div>:<div className="settings-card"><h2>Sign in for support</h2><p>Support tickets are linked to your school account so your team can see the full history.</p><Link to="/login" className="button button-dark">Sign in <ArrowRight size={15}/></Link></div>}</main><Footer/></>;
}
function Legal({ kind }) { const copy = { privacy: { eyebrow: 'Privacy, thoughtfully', title: 'Care comes first.', body: 'This starter privacy notice explains the intended handling of school and children’s information. It is not a legal opinion or a final legal policy. Before production, the platform operator and every school must have this reviewed by qualified counsel for their actual services, data flows, retention, roles, and applicable law.', sections: [['What information may be used', 'Account details, school membership, attendance, homework, admissions, fee records, and device/session records may be processed to operate the service. Collect only what a school needs.'], ['Why it is used', 'To deliver school administration, family access, admission communication, safety, support, and service billing. Each school is responsible for documenting lawful instructions and notices for its users.'], ['Children and guardians', 'A school must confirm the right guardian relationship and provide age-appropriate information. Guardian consent and age-assurance processes need to be configured and legally reviewed before collecting children’s personal information.'], ['Access and security', 'School records are separated by school membership and role. Owners and principals can review school activity. Staff should receive only the access needed for their work. Platform operators should use strong authentication and audit privileged access.'], ['Retention and requests', 'Define retention periods for each data category, a process for correction and deletion requests, backup expiry, and handling when a school leaves the service. This prototype does not yet provide a complete self-service export or erasure workflow.'], ['Contact', 'Add your legal entity name, privacy contact, grievance contact, and verified support address before publishing this notice.']] }, terms: { eyebrow: 'Terms of service', title: 'Clear expectations.', body: 'This is starter copy for a SaaS agreement and needs review by qualified counsel before you publish it. Replace every product, entity, pricing, and jurisdiction detail with your real operating terms.', sections: [['Who provides the service', 'Identify the platform operator, each school customer, and which party is responsible for school records and user instructions.'], ['Accounts and school access', 'Users must keep invitation codes and login details private. School owners are responsible for appointing staff, assigning roles, and removing access promptly.'], ['Plans and billing', 'Plan prices, payment dates, tax, SMS bundles, renewal, refunds, suspension, and cancellation terms must be set in the platform’s billing configuration and disclosed before purchase.'], ['Acceptable use', 'Do not use the service to send unlawful messages, expose children’s information, or access another school’s information. Report security incidents through the verified support channel.'], ['Availability and support', 'Publish the support response times, maintenance process, backup objectives, and incident notification route that you can actually meet.'], ['Contact and governing law', 'Add legal entity details, contact information, jurisdiction, and dispute process after legal review.']] }, cookies: { eyebrow: 'Cookie notice', title: 'Small details, made clear.', body: 'This page is a starter notice. Add only the cookies and device storage that the deployed application actually uses, and obtain any consent that applies to your use case.', sections: [['Essential session storage', 'The current browser interface stores a short-lived bearer token in local storage for this prototype. A production deployment should move authentication into secure, HttpOnly cookies or another reviewed mobile/web session strategy.'], ['Preferences and analytics', 'No analytics or advertising scripts are included in this starter. If you add them, disclose their purpose, provider, and retention and provide controls where required.'], ['Your choices', 'Users can sign out to remove the local prototype token. Provide a complete cookie preference control before adding non-essential cookies.']] } }[kind]; return <><Nav /><main className="legal-shell"><SectionLabel>{copy.eyebrow}</SectionLabel><h1>{copy.title}</h1><p className="legal-intro">{copy.body}</p><div className="legal-sections">{copy.sections.map(([h, p], index) => <section key={h}><span className="legal-number">{String(index + 1).padStart(2, '0')}</span><div><h2>{h}</h2><p>{p}</p></div></section>)}</div><div className="legal-review"><Shield size={17}/><span>Before launch, have an Indian privacy lawyer review these pages against the final service, consent flow, retention rules, and relevant DPDP requirements.</span></div></main><Footer /></>; }
function Frame({ children }) { return <><Nav /><main className="dashboard-shell">{children}</main><Footer /></>; }
export default function App() { return <PreferenceProvider><Toaster position="top-right" richColors closeButton/><AnimatePresence mode="wait"><Routes><Route path="/" element={<Home />}/><Route path="/schools/:slug" element={<SchoolDetail />}/><Route path="/register" element={<Register />}/><Route path="/billing" element={<Billing Frame={Frame}/>}/><Route path="/forgot-password" element={<ForgotPassword Layout={AuthLayout}/>}/><Route path="/reset-password" element={<ResetPassword Layout={AuthLayout}/>}/><Route path="/verify-email" element={<VerifyEmail Layout={AuthLayout}/>}/><Route path="/login" element={<Login />}/><Route path="/join/:code" element={<Join />}/><Route path="/download" element={<Download />}/><Route path="/dashboard" element={<Dashboard />}/><Route path="/settings" element={<SettingsPremium />}/><Route path="/workspace" element={<Workspace />}/><Route path="/platform-admin" element={<PlatformAdmin />}/><Route path="/support" element={<SupportPage />}/><Route path="/privacy" element={<Legal kind="privacy"/>}/><Route path="/terms" element={<Legal kind="terms"/>}/><Route path="/cookies" element={<Legal kind="cookies"/>}/><Route path="*" element={<main className="loading-panel"><h1>That page isn't here.</h1><Link to="/" className="button button-dark">Go home <ArrowRight size={16}/></Link></main>}/></Routes></AnimatePresence></PreferenceProvider>; }
